    """Extract the uncovered 3-column tile indicated by the color-8 mask."""
    h, w = len(grid), len(grid[0])
    marked = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0, r1 = min(r for r, c in marked), max(r for r, c in marked)
    c0, c1 = min(c for r, c in marked), max(c for r, c in marked)

    # Find the row-reflection axis that best explains the unmasked canvas.
    best = (-1.0, 0)
    for axis_sum in range(2 * h - 1):
        same = total = 0
        for r in range(h):
            rr = axis_sum - r
            if not 0 <= rr < h:
                continue
            for c in range(w):
                if grid[r][c] != 8 and grid[rr][c] != 8:
                    total += 1
                    same += grid[r][c] == grid[rr][c]
        score = same / total if total else 0
        if score > best[0]:
            best = score, axis_sum
    axis_sum = best[1]

    # The 8s obscure a tile whose cells are the reflection of the visible copy.
    out = []
    for r in range(r0, r1 + 1):
